import React, { createContext, useContext, useState, useEffect } from 'react';
import axios from 'axios';
import { ENDPOINTS } from '../config/apiConfig';
import { getToken, setToken, removeToken, parseToken, getAuthHeader } from '../utils/authUtils';

// Create context
const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Check if token exists and fetch user data when component mounts
  useEffect(() => {
    const initializeAuth = async () => {
      const token = getToken();

      if (token) {
        try {
          const userInfo = await fetchCurrentUser();
          setCurrentUser(userInfo);
        } catch (err) {
          // Token might be invalid or expired
          console.error('Error loading user data:', err);
          logout();
        } finally {
          setLoading(false);
        }
      } else {
        setLoading(false);
      }
    };

    initializeAuth();
  }, []);

  // Fetch current user data from API
  const fetchCurrentUser = async () => {
    try {
      const response = await axios.get(ENDPOINTS.AUTH.CURRENT_USER, {
        headers: {
          ...getAuthHeader()
        }
      });

      return response.data;
    } catch (err) {
      throw err;
    }
  };

  // Login user with username and password
  const login = async (username, password) => {
    setError(null);

    try {
      const response = await axios.post(ENDPOINTS.AUTH.LOGIN, {
        username,
        password
      });

      const { access_token } = response.data;

      // Store token
      setToken(access_token);

      // Fetch and set user data
      const userInfo = await fetchCurrentUser();
      setCurrentUser(userInfo);

      return userInfo;
    } catch (err) {
      let errorMessage = 'Login failed. Please check your credentials.';

      if (err.response) {
        // Handle specific error responses
        if (err.response.status === 401) {
          errorMessage = 'Invalid username or password.';
        } else if (err.response.data && err.response.data.detail) {
          errorMessage = err.response.data.detail;
        }
      }

      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  // Register new user
  const register = async (userData) => {
    setError(null);

    try {
      await axios.post(ENDPOINTS.AUTH.REGISTER, userData);
      // Auto login after registration
      return await login(userData.username, userData.password);
    } catch (err) {
      let errorMessage = 'Registration failed. Please try again.';

      if (err.response && err.response.data) {
        // Handle specific error responses
        if (err.response.data.detail) {
          errorMessage = err.response.data.detail;
        }
      }

      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  // Logout user
  const logout = () => {
    removeToken();
    setCurrentUser(null);
  };

  const value = {
    currentUser,
    isAuthenticated: !!currentUser,
    loading,
    error,
    login,
    register,
    logout
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

// Custom hook to use the auth context
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
